import{_ as r,a0 as p,w as i,s as l,ao as m,I as a,x as e,a1 as o,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Linux有问必答：如何在CentOS或RHEL 7上修改主机名 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何在CentOS或RHEL 7上修改主机名 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何在CentOS或RHEL 7上修改主机名 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何在CentOS或RHEL 7上修改主机名 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140915 Linux FAQs with Answers--How to change hostname on CentOS or RHEL 7","title":"Linux有问必答：如何在CentOS或RHEL 7上修改主机名","tag":"201410","desc":""},"relativePath":"201410/20140915 Linux FAQs with Answers--How to change hostname on CentOS or RHEL 7.md","filePath":"[post].md"}'),u={name:"201410/20140915 Linux FAQs with Answers--How to change hostname on CentOS or RHEL 7.md"};function h(d,t,L,C,c,x){const n=p("Link");return i(),l("div",null,[t[11]||(t[11]=m(`<h1 id="linux有问必答-如何在centos或rhel-7上修改主机名" tabindex="-1">Linux有问必答：如何在CentOS或RHEL 7上修改主机名 <a class="header-anchor" href="#linux有问必答-如何在centos或rhel-7上修改主机名" aria-label="Permalink to “Linux有问必答：如何在CentOS或RHEL 7上修改主机名”">​</a></h1><blockquote><p>问题：在CentOS/RHEL 7上修改主机名的正确方法是什么（永久或临时）？</p></blockquote><p>在CentOS或RHEL中，有三种定义的主机名:a、静态的（static），b、瞬态的（transient），以及 c、灵活的（pretty）。“静态”主机名也称为内核主机名，是系统在启动时从/etc/hostname自动初始化的主机名。“瞬态”主机名是在系统运行时临时分配的主机名，例如，通过DHCP或mDNS服务器分配。静态主机名和瞬态主机名都遵从作为互联网域名同样的字符限制规则。而另一方面，“灵活”主机名则允许使用自由形式（包括特殊/空白字符）的主机名，以展示给终端用户（如Dan&#39;s Computer）。</p><p>在CentOS/RHEL 7中，有个叫hostnamectl的命令行工具，它允许你查看或修改与主机名相关的配置。</p><p>要查看主机名相关的设置：</p><pre><code>$ hostnamectl status 
</code></pre><p><img src="https://farm4.staticflickr.com/3844/15113861225_e0e19783a7.jpg" alt=""></p><p>只查看静态、瞬态或灵活主机名，分别使用“--static”，“--transient”或“--pretty”选项。</p><pre><code> $ hostnamectl status [--static|--transient|--pretty] 
</code></pre><p>要同时修改所有三个主机名：静态、瞬态和灵活主机名：</p><pre><code>$ sudo hostnamectl set-hostname &lt;host-name&gt; 
</code></pre><p><img src="https://farm4.staticflickr.com/3855/15113489172_4e25ac87fa_z.jpg" alt=""></p><p>就像上面展示的那样，在修改静态/瞬态主机名时，任何特殊字符或空白字符会被移除，而提供的参数中的任何大写字母会自动转化为小写。一旦修改了静态主机名，/etc/hostname 将被自动更新。然而，/etc/hosts 不会更新以保存所做的修改，所以你需要手动更新/etc/hosts。</p><p>如果你只想修改特定的主机名（静态，瞬态或灵活），你可以使用“--static”，“--transient”或“--pretty”选项。</p><p>例如，要永久修改主机名，你可以修改静态主机名：</p><pre><code> $ sudo hostnamectl --static set-hostname &lt;host-name&gt; 
</code></pre><p>注意，你不必重启机器以激活永久主机名修改。上面的命令会立即修改内核主机名。注销并重新登入后在命令行提示来观察新的静态主机名。</p><hr>`,18)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://ask.xmodulo.com/change-hostname-centos-rhel-7.html"},{default:s(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/change-hostname-centos-rhel-7.html",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("译者：",-1)),o(n,{href:"https://github.com/GOLinux"},{default:s(()=>[...t[2]||(t[2]=[e("GOLinux",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),o(n,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const g=r(u,[["render",h]]);export{_ as __pageData,g as default};
